            others = [o for o in others if not ids.same_issue(o["item"], key)]
            others.append(_other(entry["judged"]["comment_id"], entry["item"], entry["state"], j["parsed"], [], login))
            for n in j["reserve"]:
                _add_usage(usage, n, key)
    return out

